-#}

  Planet TVL

  {{now()|date(format="%Y-%m-%dT%H:%M:%SZ")}}
  https://planet.tvl.fyi

    {{ PKG_NAME }} by {{ PKG_AUTHORS }}

  https://planet.tvl.fyi/logo.svg

  {% for entry in entries %}

      {{ entry.id }}/planet.tvl.fyi
      {% if entry.title -%}
        {{ entry.title.content|striptags }}
      {% endif -%}
      {% for link in entry.links %}

      {% endfor %}
      {% if entry.updated %}
        {{ entry.updated }}
      {% endif %}
      {% if entry.published %}
        {{ entry.published }}
      {% endif %}
      {% if entry.summary -%}

          {{ entry.summary.content|striptags }}

      {% endif -%}
      {% for author in entry.authors %}

          {% if author.name -%}
            {{ author.name }}
          {% endif -%}
          {% if author.email -%}
            {{ author.email }}
          {% endif -%}
          {% if author.uri -%}
            {{ author.uri|safe }}
          {% endif -%}

      {% endfor %}
      {% if entry.content -%}

          {% if entry.content.content_type in ["application/xhtml+xml", "text/xhtml", "xhtml"] %}
            {{ entry.content.body|striptags }}
          {% else %}{# html is sanitized by feed_rs for type=html #}
            {{ entry.content.body }}
          {% endif -%}

      {% endif -%}

  {% endfor %}
